"""Void Dragon animations (your "ancient celestial dragon" set): 17-frame wing-stroke flight loop and the
charged wing-beat used while it opens a black hole. Frames are 168x128 like the other HD dragons."""
import base64, zlib, math
import pygame

FRAMES = {
  'fly': (17, ''),
}
MOUTH = [(137, 47), (137, 48), (137, 45), (137, 42), (138, 41), (138, 42), (138, 40), (138, 40), (138, 42), (138, 44), (138, 45), (137, 47), (137, 48), (137, 50), (137, 48), (137, 45), (137, 41)]                                       # jaw position (in the 168x128 frame) for each flight frame
_RAW, _F, _R = {}, {}, {}
W, H = 168, 128


def _frame(name, i):
  n, data = FRAMES[name]
  i %= n
  k = (name, i)
  s = _F.get(k)
  if s is None:
    raw = _RAW.get(name)
    if raw is None:
      raw = _RAW[name] = zlib.decompress(base64.b64decode(data))
    m = W * H * 4
    s = _F[k] = pygame.image.frombuffer(raw[i * m:(i + 1) * m], (W, H), 'RGBA').copy()
  return s


def void_frame(name, i, tb=0):
  """flight frame i, tilted by tb steps (6 degrees each, nose down for +). It keeps flapping while it attacks."""
  name = 'fly'
  if not tb:
    return _frame(name, i)
  k = (name, i % FRAMES[name][0], tb)
  s = _R.get(k)
  if s is None:
    src = _frame(name, i)
    r = pygame.transform.rotate(src, -tb * 6)
    s = pygame.Surface((W, H), pygame.SRCALPHA)
    s.blit(r, (W // 2 - r.get_width() // 2, H // 2 - r.get_height() // 2))
    _R[k] = s
  return s


def void_fly_index(wing):
  """one frame every 2 game frames while flapping (wing grows 0.38 a frame), slower while gliding"""
  return int(wing / 0.76) % 17


def void_mouth(i, tb=0):
  x, y = MOUTH[i % 17]
  if tb:                                          # follow the tilt (rotation about the frame centre)
    a = math.radians(tb * 6)
    dx, dy = x - W / 2.0, y - H / 2.0
    x, y = W / 2.0 + dx * math.cos(a) - dy * math.sin(a), H / 2.0 + dx * math.sin(a) + dy * math.cos(a)
  return x, y
